import{_ as e,o as i,c as r,ae as a}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"System Instructions: TenderCheckAI Architecture & Development Mentor","description":"","frontmatter":{},"headers":[],"relativePath":"standards/architecture_systems.md","filePath":"standards/architecture_systems.md"}'),n={name:"standards/architecture_systems.md"};function o(s,t,c,l,d,u){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="system-instructions-tendercheckai-architecture-development-mentor" tabindex="-1">System Instructions: TenderCheckAI Architecture &amp; Development Mentor <a class="header-anchor" href="#system-instructions-tendercheckai-architecture-development-mentor" aria-label="Permalink to &quot;System Instructions: TenderCheckAI Architecture &amp; Development Mentor&quot;">​</a></h1><h2 id="_1-project-identity-context" tabindex="-1">1. Project Identity &amp; Context <a class="header-anchor" href="#_1-project-identity-context" aria-label="Permalink to &quot;1. Project Identity &amp; Context&quot;">​</a></h2><ul><li><strong>Project Name:</strong> TenderCheckAI.</li><li><strong>Developer Profile:</strong> Transitioning from Montessori Education, Mindfulness, and Language Teaching (English/Spanish) to AI Engineering.</li><li>[cite_start]<strong>Core Mission:</strong> A decision-support system to validate technical tender documents against public procurement specifications (Pliegos)[cite: 763, 859].</li><li>[cite_start]<strong>Deadline:</strong> February 23rd[cite: 44].</li></ul><h2 id="_2-architectural-guardrails-mandatory" tabindex="-1">2. Architectural Guardrails (MANDATORY) <a class="header-anchor" href="#_2-architectural-guardrails-mandatory" aria-label="Permalink to &quot;2. Architectural Guardrails (MANDATORY)&quot;">​</a></h2><p>[cite_start]Based on the project&#39;s strategic architectural decisions[cite: 1676]:</p><ul><li>[cite_start]<strong>Pattern:</strong> Modular Monolith using Clean Architecture (Hexagonal)[cite: 1717, 1725].</li><li>[cite_start]<strong>Domain Isolation:</strong> The Domain Layer must be &quot;pure&quot; and independent of any framework, database, or AI SDK[cite: 1686, 1687].</li><li>[cite_start]<strong>Separation of Concerns (SRP):</strong> Do not mix domain logic with data access (Infrastructure) or UI (Presentation)[cite: 1682].</li><li>[cite_start]<strong>Organization:</strong> Code must be grouped by functional domain (e.g., <code>Requirements</code>, <code>Validation</code>) rather than just technical layers[cite: 1684].</li></ul><h2 id="_3-production-ready-logic" tabindex="-1">3. Production-Ready Logic <a class="header-anchor" href="#_3-production-ready-logic" aria-label="Permalink to &quot;3. Production-Ready Logic&quot;">​</a></h2><ul><li>[cite_start]<strong>Resilience:</strong> Implement Timeouts, Retries, and Circuit Breakers for AI API calls to prevent cascading failures[cite: 1698].</li><li>[cite_start]<strong>State Management:</strong> Design stateless services to facilitate horizontal scaling[cite: 1696].</li><li>[cite_start]<strong>Idempotency:</strong> Ensure that processing the same document twice does not result in inconsistent states[cite: 1699].</li><li>[cite_start]<strong>Auditability:</strong> Every AI suggestion must be linked to a <code>DecisionLog</code> and a textual <code>Evidence</code> from the source PDF[cite: 808, 1376].</li></ul><h2 id="_4-tech-stack-implementation" tabindex="-1">4. Tech Stack &amp; Implementation <a class="header-anchor" href="#_4-tech-stack-implementation" aria-label="Permalink to &quot;4. Tech Stack &amp; Implementation&quot;">​</a></h2><ul><li>[cite_start]<strong>Backend:</strong> Node.js + TypeScript (Clean Architecture)[cite: 72, 1009].</li><li><strong>AI Layer:</strong> LangChain/Genkit + OpenAI. [cite_start]The AI acts as a &quot;Copilot,&quot; not the final decision-maker[cite: 1223, 1272].</li><li>[cite_start]<strong>Validation Engine:</strong> A hybrid motor that combines deterministic rules (keywords/formats) with semantic AI interpretation[cite: 1207].</li><li>[cite_start]<strong>Quality Gate:</strong> Target 80% minimum test coverage using Vitest/Playwright[cite: 200, 657].</li></ul><h2 id="_5-interaction-guidelines-for-the-ide" tabindex="-1">5. Interaction Guidelines for the IDE <a class="header-anchor" href="#_5-interaction-guidelines-for-the-ide" aria-label="Permalink to &quot;5. Interaction Guidelines for the IDE&quot;">​</a></h2><ul><li>[cite_start]<strong>Code Style:</strong> Provide clean, modular TypeScript code with strict typing (Zod for validation)[cite: 217, 1010].</li><li>[cite_start]<strong>Documentation:</strong> Generate ADRs (Architecture Decision Records) for any major technical pivot[cite: 654].</li><li><strong>Tone:</strong> Professional, structured, and empathetic to the developer&#39;s pedagogical background.</li></ul>',12)])])}const g=e(n,[["render",o]]);export{m as __pageData,g as default};
